// Claude's review tests for the A5 socket editor. agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, newProject, type SocketMock, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(sockets: SocketMock[] = [], withSecondScenario = false): Promise<{ page: Page; panel: Page }> {
  const project = newProject('p1', fixture.origin);
  project.scenarios[0]!.sockets = sockets;
  if (withSecondScenario) project.scenarios.push({ id: 's2', name: 'Two', mocks: [] });
  await session.setState({ ...emptyState(), projects: [project], enabledOrigins: [fixture.origin] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  await page.addScriptTag({ url: '/signalr.js' });
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  await panel.getByTestId('tab-mocks').click();
  return { page, panel };
}

async function newSocket(panel: Page): Promise<void> {
  await panel.getByTestId('socket-new').click();
  // The editor opens on the new socket once storage reports it.
  await expect(panel.getByTestId('socket-pattern')).toHaveValue('/hub');
}

test('a new SignalR socket: defaults, then pattern, a push and a reply, saved and served', async () => {
  const { page, panel } = await open();
  try {
    await newSocket(panel);
    await expect(panel.getByTestId('socket-kind')).toHaveValue('signalr');
    await expect(panel.getByTestId('socket-row')).toHaveCount(1);
    await panel.getByTestId('socket-name').fill('Chat');
    await panel.getByTestId('socket-pattern').fill('/hubs/chat');

    await panel.getByTestId('push-add').click();
    const push = panel.getByTestId('push-row').first();
    await push.getByTestId('push-after').fill('20');
    await push.getByTestId('push-target').fill('Receive');
    await push.getByTestId('push-data').fill('["bot","hi"]');

    await panel.getByTestId('reply-add').click();
    const reply = panel.getByTestId('reply-row').first();
    await reply.getByTestId('reply-when').fill('Send');
    await expect(reply.getByTestId('reply-respond')).toHaveValue('fixed');
    await reply.getByTestId('reply-result').fill('{"ok":true}');
    await panel.getByTestId('socket-save').click();
    await expect(panel.getByTestId('socket-row')).toContainText('Chat');

    const saved = (await readState()).projects[0]!.scenarios[0]!.sockets![0]!;
    expect(saved).toMatchObject({
      name: 'Chat',
      kind: 'signalr',
      urlPattern: '/hubs/chat',
      enabled: true,
      onConnect: [{ afterMs: 20, target: 'Receive', data: '["bot","hi"]' }],
      replies: [{ when: 'Send', respond: 'fixed', result: '{"ok":true}', pushes: [] }],
    });
    expect(typeof saved.id).toBe('string');
    expect(typeof saved.onConnect[0]!.id).toBe('string');
    expect(typeof saved.replies[0]!.id).toBe('string');

    const out = await page.evaluate(async () => {
      const signalR = (window as unknown as { signalR: any }).signalR; // eslint-disable-line @typescript-eslint/no-explicit-any
      const got: unknown[] = [];
      const c = new signalR.HubConnectionBuilder().withUrl('/hubs/chat').configureLogging(signalR.LogLevel.None).build();
      c.on('Receive', (a: string, b: string) => got.push([a, b]));
      await c.start();
      for (let i = 0; i < 50 && got.length < 1; i++) await new Promise((r) => setTimeout(r, 20));
      const r = await c.invoke('Send', 'x');
      await c.stop();
      return { got, r };
    });
    expect(out).toEqual({ got: [['bot', 'hi']], r: { ok: true } });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a plain socket hides the target field, and a code reply answers', async () => {
  const { page, panel } = await open();
  try {
    await newSocket(panel);
    await panel.getByTestId('socket-kind').selectOption('plain');
    await panel.getByTestId('socket-pattern').fill('/ws/up');
    await panel.getByTestId('push-add').click();
    await expect(panel.getByTestId('push-row').first().getByTestId('push-target')).toHaveCount(0);
    await panel.getByTestId('push-row').first().getByTestId('push-data').fill('welcome');

    await panel.getByTestId('reply-add').click();
    const reply = panel.getByTestId('reply-row').first();
    await reply.getByTestId('reply-when').fill('up:');
    await reply.getByTestId('reply-respond').selectOption('code');
    await expect(reply.getByTestId('reply-result')).toHaveCount(0);
    await reply.getByTestId('reply-code').fill('return String(body).slice(3).toUpperCase();');
    await panel.getByTestId('socket-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.sockets?.[0]?.kind).toBe('plain');

    const got = await page.evaluate(async () => {
      const ws = new WebSocket(`${location.origin.replace('http', 'ws')}/ws/up`);
      const msgs: string[] = [];
      ws.onmessage = (e) => msgs.push(String(e.data));
      await new Promise((r) => (ws.onopen = r));
      ws.send('up:loud');
      for (let i = 0; i < 100 && msgs.length < 2; i++) await new Promise((r) => setTimeout(r, 20));
      ws.close();
      return msgs;
    });
    expect(got).toEqual(['welcome', 'LOUD']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a reply can send follow-up messages', async () => {
  const { page, panel } = await open();
  try {
    await newSocket(panel);
    await panel.getByTestId('socket-pattern').fill('/hubs/f');
    await panel.getByTestId('reply-add').click();
    const reply = panel.getByTestId('reply-row').first();
    await reply.getByTestId('reply-when').fill('Go');
    await reply.getByTestId('reply-push-add').click();
    const p = reply.getByTestId('push-row').first();
    await p.getByTestId('push-target').fill('Done');
    await p.getByTestId('push-data').fill('[7]');
    await panel.getByTestId('socket-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.sockets?.[0]?.replies[0]?.pushes.length).toBe(1);

    const out = await page.evaluate(async () => {
      const signalR = (window as unknown as { signalR: any }).signalR; // eslint-disable-line @typescript-eslint/no-explicit-any
      const got: unknown[] = [];
      const c = new signalR.HubConnectionBuilder().withUrl('/hubs/f').configureLogging(signalR.LogLevel.None).build();
      c.on('Done', (n: number) => got.push(n));
      await c.start();
      await c.invoke('Go');
      for (let i = 0; i < 50 && got.length < 1; i++) await new Promise((r) => setTimeout(r, 20));
      await c.stop();
      return got;
    });
    expect(out).toEqual([7]);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('bad SignalR arguments or a bad pattern block Save', async () => {
  const { page, panel } = await open();
  try {
    await newSocket(panel);
    await panel.getByTestId('push-add').click();
    await panel.getByTestId('push-row').first().getByTestId('push-data').fill('not json');
    await expect(panel.getByTestId('push-data-error')).toHaveText('Arguments must be a JSON array');
    await expect(panel.getByTestId('socket-save')).toBeDisabled();
    await panel.getByTestId('push-row').first().getByTestId('push-data').fill('["ok"]');
    await expect(panel.getByTestId('push-data-error')).toHaveCount(0);
    await expect(panel.getByTestId('socket-save')).toBeEnabled();

    await panel.getByTestId('socket-pattern').fill('/hubs/(');
    await expect(panel.getByTestId('socket-pattern-error')).toBeVisible();
    await expect(panel.getByTestId('socket-save')).toBeDisabled();
  } finally {
    await panel.close();
    await page.close();
  }
});

const ready: SocketMock = {
  id: 'ready',
  name: 'Ready',
  enabled: true,
  kind: 'plain',
  urlPattern: '/ws/ready',
  createdAt: 0,
  onConnect: [{ id: 'w', afterMs: 0, target: '', data: 'hello' }],
  replies: [],
};

test('the row checkbox turns a socket off, and the page then gets the native socket', async () => {
  const { page, panel } = await open([ready]);
  try {
    const row = panel.getByTestId('socket-row').first();
    await expect(row).toContainText('Ready');
    await row.getByTestId('socket-enabled').uncheck();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.sockets![0]!.enabled).toBe(false);
    await page.reload();
    const code = await page.evaluate(async () => {
      const ws = new WebSocket(`${location.origin.replace('http', 'ws')}/ws/ready`);
      return new Promise<number>((r) => (ws.onclose = (e) => r(e.code)));
    });
    expect(code).toBe(1006);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('clicking a socket row opens it; Delete removes it; mocks and sockets do not share the editor', async () => {
  const { page, panel } = await open([ready]);
  try {
    await panel.getByTestId('socket-row').first().click();
    await expect(panel.getByTestId('socket-name')).toHaveValue('Ready');
    await expect(panel.getByTestId('mock-save')).toHaveCount(0);
    await expect(panel.getByTestId('push-row').first().getByTestId('push-data')).toHaveValue('hello');

    await panel.getByTestId('mock-new').click();
    await expect(panel.getByTestId('field-pattern')).toHaveValue('/');
    await expect(panel.getByTestId('socket-save')).toHaveCount(0);

    await panel.getByTestId('socket-row').first().click();
    await panel.getByTestId('socket-delete').click();
    await expect(panel.getByTestId('socket-row')).toHaveCount(0);
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.sockets ?? []).toEqual([]);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a new socket lands in the selected scenario', async () => {
  const { page, panel } = await open([], true);
  try {
    await panel.locator('.scenario-group-header', { hasText: 'Two' }).click();
    await newSocket(panel);
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[1]!.sockets?.length ?? 0).toBe(1);
    expect((await readState()).projects[0]!.scenarios[0]!.sockets ?? []).toEqual([]);
  } finally {
    await panel.close();
    await page.close();
  }
});
